var seen sync.Map // key -> time.Time

func claim(id string) bool {
    _, loaded := seen.LoadOrStore(id, time.Now())
    return !loaded // false => another delivery already claimed this id
}

func (h *Handler) Handle(ctx context.Context, m Message) error {
    if !claim(m.IdempotencyKey) { return h.ack(ctx, m) } // duplicate: absorb
    return h.applyEffects(ctx, m)
}

